return [msg, null];

const settings = global.get('aiChatSettings') || {};
const body = msg.payload;

if (msg.statusCode !== 200 || !body || !body.content) {
    const errText = (body && body.error && body.error.message)
        ? body.error.message
        : 'API error (HTTP ' + msg.statusCode + ')';
    node.status({ fill: 'red', shape: 'ring', text: 'HTTP ' + msg.statusCode });
    return [{ topic: 'assistant_error', payload: errText }, null];
}

let history = flow.get('chatHistory') || [];
const text = body.content.filter(b => b.type === 'text').map(b => b.text).join('\n').trim();

if (body.stop_reason === 'tool_use') {
    const loops = (flow.get('chatToolLoops') || 0) + 1;
    flow.set('chatToolLoops', loops);
    history.push({ role: 'assistant', content: body.content });

    const BMS = global.get('BMS');
    const results = [];
    body.content.filter(b => b.type === 'tool_use').forEach(b => {
        let result;
        if (b.name === 'apply_bms_config' && BMS && BMS.applyConfig) result = BMS.applyConfig(b.input);
        else result = { errors: ['unknown tool: ' + b.name] };
        results.push({ type: 'tool_result', tool_use_id: b.id, content: JSON.stringify(result) });

        const ok = !(result.errors || []).length;
        const clean = ok && !(result.unknownFacts || []).length;
        const summary = ok
            ? '✓ Configuration applied: ' + Object.entries(result.counts || {}).map(([k, v]) => v + ' ' + k).join(', ')
              + ((result.unknownFacts || []).length ? ' — ⚠ unknown facts: ' + result.unknownFacts.join(', ') : '')
            : '✗ Apply failed: ' + result.errors.join('; ');
        node.send([{ topic: 'tool_applied', payload: { text: summary, ok: clean } }, null]);
    });
    history.push({ role: 'user', content: results });
    flow.set('chatHistory', history);

    if (text) node.send([{ topic: 'assistant_progress', payload: text }, null]);

    if (loops > 5) {
        return [{ topic: 'assistant_error', payload: 'Stopped after 5 consecutive tool calls — ask me to continue if needed.' }, null];
    }

    const buildPrompt = global.get('buildAIPrompt');
    node.status({ fill: 'blue', shape: 'dot', text: 'tool round ' + loops });
    return [null, {
        url: 'https://api.anthropic.com/v1/messages',
        method: 'POST',
        headers: { 'x-api-key': settings.apiKey, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
        payload: {
            model: settings.model || 'claude-sonnet-4-6',
            max_tokens: 8192,
            system: buildPrompt ? buildPrompt('tool') : 'You are a BMS automation expert.',
            messages: history,
            tools: global.get('aiChatTools') || []
        }
    }];
}

history.push({ role: 'assistant', content: text || '(empty response)' });
flow.set('chatHistory', history);
node.status({ fill: 'green', shape: 'dot', text: 'replied' });
return [{ topic: 'assistant_message', payload: text || '(empty response)' }, null];

